# Generated by build.py from recipe.yml for recipe sftp-offer-a-single-cipher. Do not edit.
set -e
cd "$(dirname "$0")"
ssh-keygen -q -t rsa -b 3072 -N "" -f host_key
ssh-keygen -q -t rsa -b 3072 -N "" -f client_key
surl --ssh-ciphers aes256-ctr --ssh-macs hmac-sha2-256 --directory site --hostkey host_key --authorized-keys alice:client_key.pub sftp://127.0.0.1:8080/ &
sleep 1
sftp -v -b get.sftp -P 8080 -i client_key -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o GlobalKnownHostsFile=/dev/null alice@127.0.0.1 2>&1
kill $(jobs -p)
